import React, { useState, useEffect } from "react";
import "./navbar.css";

const PlayerSearch = () => {
  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState([]);

  const fetchPlayersByName = async (name) => {
    try {
      const response = await fetch(`http://localhost:8080/search-players?name=${name}`);
      if (response.ok) {
        const data = await response.json();
        return data.players; // فرض کنید سرور لیستی از بازیکنان را در players بازمی‌گرداند
      } else {
        console.error("Failed to fetch search results.");
        return [];
      }
    } catch (error) {
      console.error("Error fetching search results:", error);
      return [];
    }
  };

  const handleSearch = async (e) => {
    const value = e.target.value;
    setSearchTerm(value);
    if (value.trim()) {
      const results = await fetchPlayersByName(value);
      setSearchResults(results);
    } else {
      setSearchResults([]);
    }
  };

  const handleFollow = (playerId) => {
    // API call to follow a player
    fetch(`http://localhost:8080/follow/${playerId}`, { method: "POST" })
      .then((response) => {
        if (response.ok) {
          alert("بازیکن با موفقیت دنبال شد.");
        } else {
          alert("خطا در دنبال کردن بازیکن.");
        }
      })
      .catch((error) => {
        console.error("Error following player:", error);
      });
  };

  return (
    <div className="main-container">
      <h1>جستجوی بازیکنان</h1>
      <input
        type="text"
        placeholder="نام بازیکن را وارد کنید..."
        value={searchTerm}
        onChange={handleSearch}
        className="search-input"
      />
      <div className="results-container">
        {searchResults.map((player) => (
          <div key={player.id} className="player-card">
            <p>{player.name}</p>
            <button onClick={() => handleFollow(player.id)}>دنبال کردن</button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default PlayerSearch;
